update public.settings set value = value || '{"privacy.intro":"اعتماد شما برای ما ارزشمند است. اطلاعاتی که هنگام تماس یا درخواست مشاوره در اختیار نگین خودرو قرار می‌دهید، فقط برای پاسخ‌گویی به همان درخواست استفاده می‌شود.","privacy.paragraph.0":"هنگامی که از طریق فرم مشاوره یا تماس مستقیم با ما در ارتباط قرار می‌گیرید، ممکن است نام، شماره تماس و جزئیاتی را که خودتان درباره درخواستتان بیان می‌کنید دریافت کنیم. این اطلاعات برای پیگیری درخواست، هماهنگی بازدید و ارائه راهنمایی مرتبط استفاده می‌شود.","privacy.paragraph.1":"اطلاعات تماس شما برای فروش یا بازاریابی به اشخاص دیگر واگذار نمی‌شود. دسترسی به آن صرفاً در اختیار افراد مرتبط با پاسخ‌گویی به درخواست شماست، مگر آنکه ارائه اطلاعات به موجب قانون لازم باشد.","privacy.paragraph.2":"برای پرسش درباره نحوه استفاده از اطلاعاتتان، با ما از طریق شماره تماس یا نشانی ایمیل درج‌شده در صفحه تماس ارتباط بگیرید.","terms.intro":"استفاده از وب‌سایت نگین خودرو تابع شرایط زیر است. این اطلاعات برای آشنایی اولیه تهیه شده و جایگزین توافق مکتوب معامله نیست.","terms.paragraph.0":"اطلاعات خودروها، تصاویر و قیمت‌های درج‌شده برای آشنایی اولیه ارائه می‌شوند و ممکن است با تغییر موجودی یا شرایط بازار به‌روزرسانی شوند. برای تأیید وضعیت و قیمت با مشاوران نگین خودرو تماس بگیرید.","terms.paragraph.1":"ثبت درخواست مشاوره یا تماس با نمایشگاه، تعهدی برای خرید یا فروش ایجاد نمی‌کند. هر معامله پس از بررسی خودرو و توافق طرفین در چارچوب اسناد معتبر انجام می‌شود.","terms.paragraph.2":"محتوای این وب‌سایت برای استفاده شخصی تهیه شده است. بازنشر تجاری مطالب یا تصاویر بدون اجازه کتبی مجاز نیست.","terms.paragraph.3":"نگین خودرو برای به‌روز نگه‌داشتن اطلاعات تلاش می‌کند؛ تصمیم نهایی خرید بر مبنای بازدید و بررسی اسناد و خودرو انجام می‌شود.","guide.point.0":"نیاز و سقف بودجه خود را از قبل تعیین کنید.","guide.point.1":"مشخصات، سوابق سرویس و مدارک خودرو را بررسی کنید.","guide.point.2":"بازدید و کارشناسی را با حوصله و در روشنایی مناسب انجام دهید.","guide.point.3":"پیش از تصمیم نهایی، شرایط معامله و هزینه‌های جانبی را شفاف کنید.","guide.point.4":"برای هماهنگی کارشناسی یا بازدید از مشاوران نگین خودرو کمک بگیرید.","contact.page_title":"با ما در ارتباط باشید","contact.page_intro":"برای مشاوره خرید، دریافت اطلاعات خودرو یا هماهنگی بازدید، خوشحال می‌شویم صدایتان را بشنویم.","contact.options_title":"راه‌های ارتباط با ما","contact.options_intro":"در ساعات کاری پاسخ‌گوی شما هستیم.","contact.phone_label":"تماس تلفنی","contact.email_label":"ایمیل"}'::jsonb where key='content';
